/** Cancel (scanned consumables return to stock) — POST /api/v1/ot/bookings/{booking_id}/cancel (who may call: holders of ot.booking.manage). */
export function cancelOtBookings(booking_id: number, body: OtReasonIn): Promise<OtBookingDetailOut> {
  return api<OtBookingDetailOut>("POST", `/ot/bookings/${booking_id}/cancel`, body);
}

/** Take a theater out of service / back into service — POST /api/v1/ot/theaters/{ot_id}/state (who may call: holders of ot.theater.provision or ot.booking.manage). */
export function theaterState(ot_id: number, body: TheaterStateIn): Promise<TheaterOut> {
  return api<TheaterOut>("POST", `/ot/theaters/${ot_id}/state`, body);
}

/** Surgeon requests OT time (digital queue) — POST /api/v1/ot/bookings (who may call: holders of ot.booking.request or ot.booking.manage). */
export function requestBooking(body: BookingIn): Promise<OtBookingDetailOut> {
  return api<OtBookingDetailOut>("POST", `/ot/bookings`, body, { idempotent: true });
}

/** Requested bookings waiting for a theater (priority first) — GET /api/v1/ot/queue (who may call: holders of ot.booking.manage). */
export function queue(): Promise<OtQueueItemOut[]> {
  return api<OtQueueItemOut[]>("GET", `/ot/queue`, undefined);
}

/** Calendar blocks for a time window — GET /api/v1/ot/calendar (who may call: holders of ot.booking.view or ot.booking.manage). */
export function calendar(query?: { start?: string | null; end?: string | null; ot_id?: number | null }): Promise<OtCalendarBlockOut[]> {
  return api<OtCalendarBlockOut[]>("GET", withQuery(`/ot/calendar`, query), undefined);
}

/** Assign theater + time block (double-booking impossible) — POST /api/v1/ot/bookings/{booking_id}/schedule (who may call: holders of ot.booking.manage). */
export function scheduleOtBookings(booking_id: number, body: OtScheduleIn): Promise<OtBookingDetailOut> {
  return api<OtBookingDetailOut>("POST", `/ot/bookings/${booking_id}/schedule`, body);
}

/** All theaters (incl. out-of-service) — GET /api/v1/ot/theaters (who may call: holders of ot.status.view or cssd.operate). */
export function theaters(): Promise<TheaterOut[]> {
  return api<TheaterOut[]>("GET", `/ot/theaters`, undefined);
}

/** Bookings (mine=true for a surgeon's own list) — GET /api/v1/ot/bookings (who may call: holders of ot.booking.view or ot.booking.manage). */
export function listBookings(query?: { mine?: boolean; status?: "Requested" | "Scheduled" | "InProgress" | "Cleaning" | "Completed" | "Cancelled" | "EmergencyHold" | null; limit?: number }): Promise<OtBookingListItemOut[]> {
  return api<OtBookingListItemOut[]>("GET", withQuery(`/ot/bookings`, query), undefined);
}
